import asyncio
import json
import time

import httpx
import jwt
from app.config import settings
from fastapi import HTTPException, Request
from jwt import algorithms


class JwksCache:
    def __init__(self):
        self.cache = None
        self.expires_at = 0.0
        self.last_refresh = 0.0
        self.lock = asyncio.Lock()

    async def _fetch(self):
        async with httpx.AsyncClient(timeout=5) as c:
            r = await c.get(settings.jwks_url)
            r.raise_for_status()
            self.cache = r.json()
            self.expires_at = time.time() + settings.jwks_ttl_seconds
            self.last_refresh = time.time()

    async def get(self, force: bool = False):
        async with self.lock:
            if force or not self.cache or time.time() >= self.expires_at:
                await self._fetch()
            return self.cache

    async def validate_jwt(self, token: str) -> dict:
        try:
            h = jwt.get_unverified_header(token)
            if h.get("alg") != "RS256":
                raise HTTPException(status_code=401, detail="Unsupported JWT algorithm")
            kid = h.get("kid")
            if not kid:
                raise HTTPException(status_code=401, detail="Missing JWT kid")
            jwks = await self.get()
            jwk = next((k for k in jwks["keys"] if k.get("kid") == kid), None)
            if not jwk:
                if time.time() - self.last_refresh >= settings.jwks_refresh_cooldown_seconds:
                    jwks = await self.get(force=True)
                    jwk = next((k for k in jwks["keys"] if k.get("kid") == kid), None)
                if not jwk:
                    raise HTTPException(status_code=401, detail="Unknown JWT signing key")
            return jwt.decode(
                token, algorithms.RSAAlgorithm.from_jwk(json.dumps(jwk)),
                algorithms=["RS256"], audience=settings.jwt_audience, issuer=settings.jwt_issuer,
            )
        except HTTPException:
            raise
        except jwt.PyJWTError as e:
            raise HTTPException(status_code=401, detail=f"Invalid JWT: {e}") from e

def bearer_token(value: str | None) -> str:
    if not value or not value.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Missing Bearer token")
    return value.removeprefix("Bearer ").strip()

def client_ip(request: Request) -> str:
    fwd = request.headers.get("x-forwarded-for")
    return fwd.split(",")[0].strip() if fwd else (request.client.host if request.client else "unknown")

def require_scope(record: dict, scope: str):
    if scope not in record["scopes"]:
        raise HTTPException(status_code=403, detail=f"Missing scope: {scope}")
